    s = str(n)
    L = len(s)
    total = 0

    # Count numbers with fewer digits than n
    for length in range(1, L):
        for x in range(0, 10):
            for y in range(x, 10):
                if x == 0 and y == 0:
                    continue
                if x == 0:
                    # y must be non-zero
                    if y == 0:
                        continue
                    cnt = 1 * (2 ** (length - 1))
                else:
                    cnt = 2 ** length
                total += cnt

    # Count numbers with exactly L digits and <= n
    for x in range(0, 10):
        for y in range(x, 10):
            if x == 0 and y == 0:
                continue
            digits = [x, y]
            if x == 0:
                first_digits = [y]
            else:
                first_digits = [x, y]
            for fd in first_digits:
                if fd > int(s[0]):
                    continue
                if fd < int(s[0]):
                    # All remaining digits can be x or y
                    total += (2 ** (L - 1))
                else:
                    # fd == s[0], need to check remaining digits
                    # Generate all possible numbers with first digit fd, followed by x or y
                    # and check if they are <= n
                    # Generate all combinations for remaining digits
                    remaining_length = L - 1
                    for bits in itertools.product([x, y], repeat=remaining_length):
                        num_str = str(fd) + ''.join(map(str, bits))
                        num = int(num_str)
                        if num <= n:
                            total += 1

