def main():
    n = int(sys.stdin.readline().strip())
    digits = list(map(int, str(n)))
    length = len(digits)
    result = 0

    # Count all numbers with fewer digits than n
    for l in range(1, length):
        result += 9 * (2 ** (l - 1))

    # Count numbers with the same number of digits as n and <= n
    for x in range(10):
        for y in range(x, 10):
            if x == y:
                # Single-digit case
                if x == 0:
                    continue
                num = 0
                valid = True
                for d in digits:
                    if x > d:
                        valid = False
                        break
                    num = num * 10 + x
                if valid and num <= n:
                    result += 1
            else:
                # Two-digit combinations
                for first in (x, y):
                    if first == 0:
                        continue
                    # Generate all possible numbers with first digit 'first' and remaining digits x or y
                    # Using a recursive approach to generate numbers digit by digit
                    def generate(pos, current, tight):
                        if pos == length:
                            return 1 if current <= n else 0
                        limit = digits[pos] if tight else 9
                        total = 0
                        for d in (x, y):
                            if d > limit:
                                continue
                            new_tight = tight and (d == limit)
                            total += generate(pos + 1, current * 10 + d, new_tight)
                        return total
                    result += generate(1, first, True)

    print(result)

